"""The words this app writes itself, in the ten languages beside English.

Everything the game names — an item, its type, the stats it rolls, the room the
character stands in — is read from the game's own translation files by
`gen_items.py`. These are the rest: the labels and sentences this tracker adds
around them, which exist nowhere in the game and so are written here, by hand,
keyed by the English they read as.

They ride out in the same file as the game's own words, which is already one per
language: a reader of another language is fetching that file anyway, and an
English reader fetches none of it. See `t` in src/say.svelte.js.

A key with no entry in a language falls back to English, so a half-finished
language is a mixed window and never a broken one — which is also how a string
added to the interface behaves until someone writes it down here.

The codes are the game's own: `sp` for Spanish, not `es`. There is no Turkish;
the community has a channel for it and the game ships no column.
"""

